package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.ExpectedStatusVO;

class ExpectedStatusValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of expected status of observed probe")
  void test_expected_status_value_holder_assign_plain_value() {
    Object holder = new Object();
    ExpectedStatusValueHolder<Object> value = new ExpectedStatusValueHolder<>(holder);
    Assertions.assertSame(holder, value.expectedStatus(1), "Setters must return the holder");
    Assertions.assertTrue(value.getExpectedStatusValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getExpectedStatus().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of expected status of observed probe")
  void test_expected_status_value_holder_assign_value_object() {
    Object holder = new Object();
    ExpectedStatusValueHolder<Object> value = new ExpectedStatusValueHolder<>(holder);
    ExpectedStatusVO vo = ExpectedStatusVO.from(1);
    Assertions.assertFalse(value.getExpectedStatusValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.expectedStatus(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getExpectedStatusValue().orElseThrow());
    Assertions.assertSame(holder, value.expectedStatus(Optional.empty()));
    Assertions.assertFalse(value.getExpectedStatusValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.expectedStatus(Optional.of(vo)));
    Assertions.assertSame(vo, value.getExpectedStatusValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of expected status of observed probe against the original")
  void test_expected_status_value_holder_read() {
    Object holder = new Object();
    ExpectedStatusValueHolder<Object> value = new ExpectedStatusValueHolder<>(holder);
    ExpectedStatusVO vo = ExpectedStatusVO.from(1);
    ExpectedStatusVO other = ExpectedStatusVO.from(1);
    ObservedProbe original = Mockito.mock(ObservedProbe.class);
    Mockito.when(original.getExpectedStatusValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readExpectedStatus(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readExpectedStatus(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.expectedStatus(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readExpectedStatus(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readExpectedStatus(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of expected status of observed probe")
  void test_expected_status_value_holder_unset() {
    Object holder = new Object();
    ExpectedStatusValueHolder<Object> value = new ExpectedStatusValueHolder<>(holder);
    ExpectedStatusVO vo = ExpectedStatusVO.from(1);
    value.expectedStatus(vo);
    Assertions.assertSame(holder, value.unsetExpectedStatusIfMatches("expectedStatus_other"));
    Assertions.assertTrue(value.getExpectedStatusValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetExpectedStatusIfMatches("expectedStatus"));
    Assertions.assertFalse(value.getExpectedStatusValue().isPresent(),
        "The field name must clear the value");
    value.expectedStatus(vo);
    Assertions.assertSame(holder, value.unsetExpectedStatus());
    Assertions.assertFalse(value.getExpectedStatusValue().isPresent(),
        "Unset must clear the value");
  }
}
